  // ─── Dynamic Live Expenses Calculations (Today, This Month, This Year, All-Time with Cash, Bank & Credit Cuts) ───
  const dynamicExpenseStats = useMemo(() => {
    const now = new Date();
    const todayStr = now.toISOString().split('T')[0];
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    let todayExp = 0;
    let todayCashExp = 0;
    let todayBankExp = 0;
    let todayCreditExp = 0;
    let todayExpCount = 0;

    let monthExp = 0;
    let monthCashExp = 0;
    let monthBankExp = 0;
    let monthCreditExp = 0;
    let monthExpCount = 0;

    let yearExp = 0;
    let yearCashExp = 0;
    let yearBankExp = 0;
    let yearCreditExp = 0;
    let yearExpCount = 0;

    let totalExp = 0;
    let totalCashExp = 0;
    let totalBankExp = 0;
    let totalCreditExp = 0;
    let totalExpCount = (expensesList || []).length;

    let rangeExp = 0;
    let rangeCashExp = 0;
    let rangeBankExp = 0;
    let rangeCreditExp = 0;
    let rangeExpCount = 0;

    (expensesList || []).forEach(e => {
      const amt = Number(e.amount) || 0;
      const methodStr = String(e.paymentSource || e.paymentMethod || '').toUpperCase();
      const isBank = methodStr.includes('BANK');
      const isCredit = methodStr.includes('CREDIT') || methodStr.includes('DUE') || methodStr.includes('UDHAR');
      const d = new Date(e.expenseDate || e.createdAt || 0);
      const dStr = !isNaN(d.getTime()) ? d.toISOString().split('T')[0] : '';

      totalExp += amt;
      if (isCredit) totalCreditExp += amt;
      else if (isBank) totalBankExp += amt;
      else totalCashExp += amt;

      if (dStr === todayStr || (!isNaN(d.getTime()) && d.toDateString() === now.toDateString())) {
        todayExp += amt;
        if (isCredit) todayCreditExp += amt;
        else if (isBank) todayBankExp += amt;
        else todayCashExp += amt;
        todayExpCount++;
      }
      if (!isNaN(d.getTime()) && d.getMonth() === currentMonth && d.getFullYear() === currentYear) {
        monthExp += amt;
        if (isCredit) monthCreditExp += amt;
        else if (isBank) monthBankExp += amt;
        else monthCashExp += amt;
        monthExpCount++;
      }
      if (!isNaN(d.getTime()) && d.getFullYear() === currentYear) {
        yearExp += amt;
        if (isCredit) yearCreditExp += amt;
        else if (isBank) yearBankExp += amt;
        else yearCashExp += amt;
        yearExpCount++;
      }
      if (isDateInSelectedRange(d)) {
        rangeExp += amt;
        if (isCredit) rangeCreditExp += amt;
        else if (isBank) rangeBankExp += amt;
        else rangeCashExp += amt;
        rangeExpCount++;
      }
    });

    let todayDamaged = 0;
    let todayCashDamaged = 0;
    let todayBankDamaged = 0;
    let todayCreditDamaged = 0;
    let todayDamagedCount = 0;

    let monthDamaged = 0;
    let monthCashDamaged = 0;
    let monthBankDamaged = 0;
    let monthCreditDamaged = 0;
    let monthDamagedCount = 0;

    let yearDamaged = 0;
    let yearCashDamaged = 0;
    let yearBankDamaged = 0;
    let yearCreditDamaged = 0;
    let yearDamagedCount = 0;

    let totalDamaged = 0;
    let totalCashDamaged = 0;
    let totalBankDamaged = 0;
    let totalCreditDamaged = 0;
    let totalDamagedEggs = 0;
    let totalDamagedCount = (damagedProductsList || []).length;

    let rangeDamaged = 0;
    let rangeCashDamaged = 0;
    let rangeBankDamaged = 0;
    let rangeCreditDamaged = 0;
    let rangeDamagedEggs = 0;
    let rangeDamagedCount = 0;

    (damagedProductsList || []).forEach(d => {
      const loss = Number(d.totalLoss) > 0
        ? Number(d.totalLoss)
        : (Number(d.lossAmount) || Number(d.amount) || ((Number(d.quantity) || 0) * (Number(d.unitPrice) || 0)));
      const methodStr = String(d.paymentMethod || d.paymentSource || 'CASH').toUpperCase();
      const isBank = methodStr.includes('BANK');
      const isCredit = methodStr.includes('CREDIT') || methodStr.includes('DUE') || methodStr.includes('CLAIM') || methodStr.includes('UDHAR');
      const isCash = !isBank && !isCredit;

      const date = new Date(d.damageDate || d.createdAt || 0);
      const dateStr = !isNaN(date.getTime()) ? date.toISOString().split('T')[0] : '';
      const eggs = Number(d.eggQuantity || d.quantity || 0) + (Number(d.petiQuantity || 0) * 360) + (Number(d.trayQuantity || 0) * 30);

      totalDamaged += loss;
      totalDamagedEggs += eggs;
      if (isCredit) totalCreditDamaged += loss;
      else if (isBank) totalBankDamaged += loss;
      else totalCashDamaged += loss;

      if (dateStr === todayStr || (!isNaN(date.getTime()) && date.toDateString() === now.toDateString())) {
        todayDamaged += loss;
        if (isCredit) todayCreditDamaged += loss;
        else if (isBank) todayBankDamaged += loss;
        else todayCashDamaged += loss;
        todayDamagedCount++;
      }
      if (!isNaN(date.getTime()) && date.getMonth() === currentMonth && date.getFullYear() === currentYear) {
        monthDamaged += loss;
        if (isCredit) monthCreditDamaged += loss;
        else if (isBank) monthBankDamaged += loss;
        else monthCashDamaged += loss;
        monthDamagedCount++;
      }
      if (!isNaN(date.getTime()) && date.getFullYear() === currentYear) {
        yearDamaged += loss;
        if (isCredit) yearCreditDamaged += loss;
        else if (isBank) yearBankDamaged += loss;
        else yearCashDamaged += loss;
        yearDamagedCount++;
      }
      if (isDateInSelectedRange(date)) {
        rangeDamaged += loss;
        rangeDamagedEggs += eggs;
        if (isCredit) rangeCreditDamaged += loss;
        else if (isBank) rangeBankDamaged += loss;
        else rangeCashDamaged += loss;
        rangeDamagedCount++;
      }
    });

    return {
      todayExp,
      todayCashExp,
      todayBankExp,
      todayCreditExp,
      todayExpCount,
      monthExp,
      monthCashExp,
      monthBankExp,
      monthCreditExp,
      monthExpCount,
      yearExp,
      yearCashExp,
      yearBankExp,
      yearCreditExp,
      yearExpCount,
      totalExp,
      totalCashExp,
      totalBankExp,
      totalCreditExp,
      totalExpCount,
      todayDamaged,
      todayCashDamaged,
      todayBankDamaged,
      todayCreditDamaged,
      todayDamagedCount,
      monthDamaged,
      monthCashDamaged,
      monthBankDamaged,
      monthCreditDamaged,
      monthDamagedCount,
      yearDamaged,
      yearCashDamaged,
      yearBankDamaged,
      yearCreditDamaged,
      yearDamagedCount,
      totalDamaged,
      totalCashDamaged,
      totalBankDamaged,
      totalCreditDamaged,
      totalDamagedEggs,
      totalDamagedCount,
      rangeExp,
      rangeCashExp,
      rangeBankExp,
      rangeCreditExp,
      rangeExpCount,
      rangeDamaged,
      rangeCashDamaged,
      rangeBankDamaged,
      rangeCreditDamaged,
      rangeDamagedEggs,
      rangeDamagedCount,
      rangeTotalLoss: rangeExp + rangeDamaged,
      todayTotalLoss: todayExp + todayDamaged,
      monthTotalLoss: monthExp + monthDamaged,
      yearTotalLoss: yearExp + yearDamaged,
      grandTotalLoss: totalExp + totalDamaged,
    };
  }, [expensesList, damagedProductsList, reportTimeframe, appliedStartDate, appliedEndDate]);

  // ─── Filtered Profit Analytics (Sales, Purchases with Peti/Tray/Egg, Expenses, Damaged Losses = Pure Net Profit) ───
  const profitReportStats = useMemo(() => {
    const now = new Date();
    const todayStr = now.toISOString().split('T')[0];
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    // 1. All-Time & Periodic Sales from unifiedSalesList (POS Bills + Online Customer Orders)
    const activeSalesData = unifiedSalesList && unifiedSalesList.length > 0 ? unifiedSalesList : (shopSalesList || []);

    const todaySales = activeSalesData.filter(s => {
      const d = new Date(s.saleDate || s.createdAt || s.date || 0);
      return !isNaN(d.getTime()) && (d.toISOString().split('T')[0] === todayStr || d.toDateString() === now.toDateString());
    });
    const todaySalesTotal = todaySales.reduce((sum, s) => sum + (Number(s.totalAmount) || 0), 0);
    const todayProfitTotal = todaySales.reduce((sum, s) => sum + (Number(s.totalProfit) || (Number(s.totalAmount) * 0.15)), 0);

    const monthSales = activeSalesData.filter(s => {
      const d = new Date(s.saleDate || s.createdAt || s.date || 0);
      return !isNaN(d.getTime()) && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const monthSalesTotal = monthSales.reduce((sum, s) => sum + (Number(s.totalAmount) || 0), 0);
    const monthProfitTotal = monthSales.reduce((sum, s) => sum + (Number(s.totalProfit) || (Number(s.totalAmount) * 0.15)), 0);

    const yearSales = activeSalesData.filter(s => {
      const d = new Date(s.saleDate || s.createdAt || s.date || 0);
      return !isNaN(d.getTime()) && d.getFullYear() === currentYear;
    });
    const yearSalesTotal = yearSales.reduce((sum, s) => sum + (Number(s.totalAmount) || 0), 0);
    const yearProfitTotal = yearSales.reduce((sum, s) => sum + (Number(s.totalProfit) || (Number(s.totalAmount) * 0.15)), 0);

    const allSalesTotal = activeSalesData.reduce((sum, s) => sum + (Number(s.totalAmount) || 0), 0);
    const allProfitTotal = activeSalesData.reduce((sum, s) => sum + (Number(s.totalProfit) || (Number(s.totalAmount) * 0.15)), 0);

    // 2. Filter Sales for active timeframe / date range
    const filteredSales = activeSalesData.filter(s => {
      if (!s) return false;
      const sDate = new Date(s.saleDate || s.createdAt || s.date || 0);
      return isDateInSelectedRange(sDate);
    });

    let grossProfit = 0;
    let totalRevenue = 0;
    filteredSales.forEach(s => {
      grossProfit += Number(s.totalProfit) || 0;
      totalRevenue += Number(s.totalAmount) || 0;
    });

    if (grossProfit === 0 && totalRevenue > 0) {
      grossProfit = Math.round(totalRevenue * 0.15);
    }
    if (grossProfit === 0 && !appliedStartDate && !appliedEndDate) {
      grossProfit = reportTimeframe === 'DAY' ? todayProfitTotal : reportTimeframe === 'MONTH' ? monthProfitTotal : reportTimeframe === 'YEAR' ? yearProfitTotal : allProfitTotal;
    }

    // Fallback to dashStats if sales list was momentarily empty
    if (totalRevenue === 0 && !appliedStartDate && !appliedEndDate) {
      totalRevenue = reportTimeframe === 'DAY' ? (dashStats.todaySales || 0) : reportTimeframe === 'MONTH' ? (dashStats.monthlySales || 0) : reportTimeframe === 'YEAR' ? (dashStats.yearlySales || 0) : (dashStats.totalRevenue || 0);
    }

    // 3. Filter Purchases / Restocks (items) for active timeframe / date range
    const filteredPurchases = (items || []).filter(p => {
      if (!p) return false;
      const pDate = new Date(p.purchaseDate || p.createdAt || p.date || 0);
      return isDateInSelectedRange(pDate);
    });

    let totalPurchasesCost = 0;
    let totalPurchasesEggs = 0;

    filteredPurchases.forEach(p => {
      const e = Number(p.eggQuantity || 0);
      const peti = Number(p.petiQuantity || 0);
      const tray = Number(p.trayQuantity || 0);
      const stock = Number(p.stock !== undefined ? p.stock : 0);
      let totalItemEggs = 0;
      if (peti > 0 || tray > 0 || e > 0) {
        totalItemEggs = Math.max(stock, (peti * 360) + (tray * 30) + (e > 0 && peti === 0 && tray === 0 ? e : 0));
      } else {
        totalItemEggs = stock;
      }
      totalPurchasesEggs += totalItemEggs;

      const cost = Number(p.totalPurchaseCost || p.purchaseCost || p.totalCost) ||
        (Number(p.costPrice || 0) * (totalItemEggs / (p.unitType === 'peti' ? 360 : p.unitType === 'tray' ? 30 : 1)));
      totalPurchasesCost += Math.round(cost);
    });

    const totalPurchasesPetis = Number((totalPurchasesEggs / 360).toFixed(1));
    const totalPurchasesTrays = Math.round(totalPurchasesEggs / 30);

    // 4. Filter Expenses for active timeframe / date range
    const filteredExpenses = (expensesList || []).filter(e => {
      if (!e) return false;
      const eDate = new Date(e.expenseDate || e.createdAt || 0);
      return isDateInSelectedRange(eDate);
    });

    const totalExpenses = filteredExpenses.reduce((sum, e) => sum + (Number(e.amount) || 0), 0);

    // 4b. Filter Vehicle Fuel Expenses for active timeframe / date range
    const filteredFuelExpenses = (fuelExpensesList || []).filter(f => {
      if (!f) return false;
      const fDate = new Date(f.expenseDate || f.createdAt || f.date || 0);
      return isDateInSelectedRange(fDate);
    });

    const totalFuelExpense = filteredFuelExpenses.reduce((sum, f) => sum + (Number(f.totalAmount) || 0), 0);

    // 5. Filter Damaged Stock Logs for active timeframe / date range
    const filteredDamaged = (damagedProductsList || []).filter(d => {
      if (!d) return false;
      const dDate = new Date(d.damageDate || d.createdAt || 0);
      return isDateInSelectedRange(dDate);
    });

    let totalDamagedLoss = 0;
    let totalDamagedEggs = 0;
    filteredDamaged.forEach(d => {
      const loss = Number(d.totalLoss) > 0
        ? Number(d.totalLoss)
        : (Number(d.lossAmount) || (Number(d.quantity || d.deductedEggs || 0) * (Number(d.unitPrice) || 0)) || 0);
      const eggs = Number(d.deductedEggs) > 0
        ? Number(d.deductedEggs)
        : (Number(d.eggQuantity || 0) + (Number(d.petiQuantity || 0) * 360) + (Number(d.trayQuantity || 0) * 30) || Number(d.quantity) || 0);
      totalDamagedLoss += loss;
      totalDamagedEggs += eggs;
    });

    // Gross Sales Revenue (pure realized sales from invoices & orders)
    // Fuel expense is tracked separately in Card 2 and as an operating cost in net profit, NOT deducted from sales
    const grossRevenue = totalRevenue;

    // 6. Final Realized Net Profit (Total Revenue - Purchases - Shop Overhead - Fuel Expense - Damaged Loss)
    const finalNetProfit = totalPurchasesCost > 0
      ? (grossRevenue - totalPurchasesCost - totalExpenses - totalFuelExpense - totalDamagedLoss)
      : (grossProfit - totalFuelExpense - totalExpenses - totalDamagedLoss);

    return {
      grossProfit,
      grossRevenue,
      totalRevenue: grossRevenue,
      totalFuelExpense,
      filteredFuelCount: filteredFuelExpenses.length,
      filteredFuelExpenses,
      totalPurchasesCost,
      totalPurchasesPetis,
      totalPurchasesTrays,
      totalPurchasesEggs,
      totalExpenses,
      totalDamagedLoss,
      totalDamagedEggs,
      finalNetProfit,
      todaySalesTotal,
      todayProfitTotal,
      monthSalesTotal,
      monthProfitTotal,
      yearSalesTotal,
      yearProfitTotal,
      allSalesTotal,
      allProfitTotal,
      filteredSalesCount: filteredSales.length,
      filteredPurchasesCount: filteredPurchases.length,
      filteredExpensesCount: filteredExpenses.length,
      filteredDamagedCount: filteredDamaged.length,
      filteredSales,
      filteredPurchases,
      filteredExpenses,
      filteredDamaged
    };
  }, [unifiedSalesList, shopSalesList, items, expensesList, damagedProductsList, fuelExpensesList, reportTimeframe, appliedStartDate, appliedEndDate, dashStats]);

  // ─── Live Dynamic Breakdown Hooks for 100% Real-time Dashboard Accuracy ───
  const salesLiveBreakdown = useMemo(() => {
    const activeData = unifiedSalesList && unifiedSalesList.length > 0 ? unifiedSalesList : (shopSalesList || []);
    const now = new Date();
    const todayStr = now.toISOString().split('T')[0];
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    const todaySales = activeData.filter(s => {
      const d = new Date(s.saleDate || s.createdAt || s.date || 0);
      return !isNaN(d.getTime()) && (d.toISOString().split('T')[0] === todayStr || d.toDateString() === now.toDateString() || d.toLocaleDateString() === now.toLocaleDateString());
    });
    const todayRevenue = todaySales.reduce((sum, s) => sum + (Number(s.totalAmount) || 0), 0) || dashStats.todaySales || 0;
    const todayOrders = todaySales.length || dashStats.todayOrdersCount || 0;
    let todayEggs = 0;
    todaySales.forEach(s => {
      (s.items || []).forEach(i => {
        todayEggs += Number(i.totalEggs || i.quantity || 0);
      });
    });
    const todayPetis = (todayEggs / 360).toFixed(1);

    const monthSales = activeData.filter(s => {
      const d = new Date(s.saleDate || s.createdAt || s.date || 0);
      return !isNaN(d.getTime()) && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const monthRevenue = monthSales.reduce((sum, s) => sum + (Number(s.totalAmount) || 0), 0) || dashStats.monthlySales || 0;
    const monthOrders = monthSales.length || dashStats.monthlyOrdersCount || 0;

    const yearSales = activeData.filter(s => {
      const d = new Date(s.saleDate || s.createdAt || s.date || 0);
      return !isNaN(d.getTime()) && d.getFullYear() === currentYear;
    });
    const yearRevenue = yearSales.reduce((sum, s) => sum + (Number(s.totalAmount) || 0), 0) || dashStats.yearlySales || 0;
    const yearOrders = yearSales.length || dashStats.yearlyOrdersCount || 0;

    const totalRevenue = activeData.reduce((sum, s) => sum + (Number(s.totalAmount) || 0), 0) || dashStats.totalRevenue || 0;
    const totalOrders = activeData.length || dashStats.totalOrders || 0;

    return {
      todayRevenue,
      todayOrders,
      todayEggs,
      todayPetis,
      monthRevenue,
      monthOrders,
      yearRevenue,
      yearOrders,
      totalRevenue,
      totalOrders
    };
  }, [unifiedSalesList, shopSalesList, dashStats]);

  const purchasesLiveBreakdown = useMemo(() => {
    let totalPurchasesCost = 0;
    let totalPurchasesEggs = 0;
    let cashPaid = 0;
    let bankPaid = 0;
    let dueBalance = 0;

    (items || []).forEach(p => {
      const e = Number(p.eggQuantity || 0);
      const peti = Number(p.petiQuantity || 0);
      const tray = Number(p.trayQuantity || 0);
      const stock = Number(p.stock !== undefined ? p.stock : 0);
      let totalItemEggs = 0;
      if (peti > 0 || tray > 0 || e > 0) {
        totalItemEggs = Math.max(stock, (peti * 360) + (tray * 30) + (e > 0 && peti === 0 && tray === 0 ? e : 0));
      } else {
        totalItemEggs = stock;
      }
      totalPurchasesEggs += totalItemEggs;

      const cost = Number(p.totalPurchaseCost || p.purchaseCost || p.totalCost) ||
        (Number(p.costPrice || 0) * (totalItemEggs / (p.unitType === 'peti' ? 360 : p.unitType === 'tray' ? 30 : 1)));
      totalPurchasesCost += Math.round(cost);

      cashPaid += Number(p.cashPaid || p.amountPaidCash || 0);
      bankPaid += Number(p.bankPaid || p.amountPaidBank || 0);
      dueBalance += Number(p.dueAmount || p.balanceDue || 0);
    });

    const totalPetisPurchased = totalPurchasesEggs > 0 ? Number((totalPurchasesEggs / 360).toFixed(1)) : (Number(dashStats.totalPetisPurchased) || 0);
    const totalTraysPurchased = totalPurchasesEggs > 0 ? Math.round(totalPurchasesEggs / 30) : (dashStats.totalTraysPurchased || 0);

    return {
      totalPetisPurchased,
      totalTraysPurchased,
      totalPurchaseCost: totalPurchasesCost || dashStats.totalPurchaseCost || 0,
      cashPaidToSupplier: cashPaid || dashStats.cashPaidToSupplier || 0,
      bankPaidToSupplier: bankPaid || dashStats.bankPaidToSupplier || 0,
      dueToSupplier: dueBalance || dashStats.dueToSupplier || 0,
    };
  }, [items, dashStats]);

  const stockLiveBreakdown = useMemo(() => {
    let totalEggs = 0;
    let totalValue = 0;
    let lowStockCount = 0;
    let outOfStockCount = 0;

    (items || []).forEach(item => {
      const e = Number(item.eggQuantity || 0);
      const peti = Number(item.petiQuantity || 0);
      const tray = Number(item.trayQuantity || 0);
      const itemStock = Number(item.stock !== undefined ? item.stock : 0);
      let totalItemEggs = 0;
      if (itemStock > 0) {
        totalItemEggs = itemStock;
      } else if (peti > 0 || tray > 0 || e > 0) {
        totalItemEggs = (peti * 360) + (tray * 30) + (e > 0 && peti === 0 && tray === 0 ? e : 0);
      }
      totalEggs += totalItemEggs;

      const price = Number(item.price || item.costPrice || 0);
      totalValue += (totalItemEggs / 30) * price;

      if (totalItemEggs === 0 || itemStock === 0) {
        outOfStockCount++;
      } else if (totalItemEggs < 300 || itemStock < 10) {
        lowStockCount++;
      }
    });

    const totalPetis = totalEggs > 0 ? Number((totalEggs / 360).toFixed(1)) : (dashStats.totalStockPetis || 0);
    const totalTrays = totalEggs > 0 ? Math.round(totalEggs / 30) : (dashStats.totalStockTrays || 0);
    const totalStockEggs = totalEggs || dashStats.totalStockEggs || 0;
    const totalInventoryValue = totalValue > 0 ? Math.round(totalValue) : (dashStats.totalInventoryValue || 0);

    return {
      totalPetis,
      totalTrays,
      totalStockEggs,
      totalInventoryValue,
      totalProducts: (items || []).length || dashStats.totalProducts || 0,
      lowStockCount,
      outOfStockCount
    };
  }, [items, dashStats]);

  // ─── Executive Net Realized Profit/Loss Breakdown for Main Dashboard ───
  const netStats = useMemo(() => {
    const todayGrossProfit = profitReportStats.todayProfitTotal || dashStats.todayProfit || 0;
    const todayExp = dynamicExpenseStats.todayExp || 0;
    const todayDmg = dynamicExpenseStats.todayDamaged || 0;
    const todayNet = todayGrossProfit - todayExp - todayDmg;

    const monthlyGrossProfit = profitReportStats.monthProfitTotal || dashStats.monthlyProfit || 0;
    const monthlyExp = dynamicExpenseStats.monthExp || 0;
    const monthlyDmg = dynamicExpenseStats.monthDamaged || 0;
    const monthlyNet = monthlyGrossProfit - monthlyExp - monthlyDmg;

    const yearlyGrossProfit = profitReportStats.yearProfitTotal || dashStats.yearlyProfit || 0;
    const yearlyExp = dynamicExpenseStats.yearExp || 0;
    const yearlyDmg = dynamicExpenseStats.yearDamaged || 0;
    const yearlyNet = yearlyGrossProfit - yearlyExp - yearlyDmg;

    const totalGrossProfit = profitReportStats.allProfitTotal || dashStats.totalProfit || 0;
    const totalExp = dynamicExpenseStats.totalExp || 0;
    const totalDmg = dynamicExpenseStats.totalDamaged || 0;
    const totalNet = totalGrossProfit - totalExp - totalDmg;

    return {
      todayGrossProfit,
      todayExp,
      todayDmg,
      todayNet,
      monthlyGrossProfit,
      monthlyExp,
      monthlyDmg,
      monthlyNet,
      yearlyGrossProfit,
      yearlyExp,
      yearlyDmg,
      yearlyNet,
      totalGrossProfit,
      totalExp,
      totalDmg,
      totalNet
    };
  }, [dashStats, profitReportStats, dynamicExpenseStats]);

  // ─── MASTER DYNAMIC "TODAY" METRICS ENGINE FOR ALL DASHBOARD & DETAIL PAGES ───
  const todayMasterMetrics = useMemo(() => {
    const now = new Date();
    const todayStr = now.toISOString().split('T')[0];
    const localToday = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;

    const isMatchToday = (raw) => {
      if (!raw) return false;
      const d = new Date(raw);
      if (isNaN(d.getTime())) return false;
      if (d.toDateString() === now.toDateString()) return true;
      const dLocal = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
      if (dLocal === localToday) return true;
      return d.toISOString().split('T')[0] === todayStr;
    };

    // 1. Unified Sales for Today
    const activeSalesData = unifiedSalesList && unifiedSalesList.length > 0 ? unifiedSalesList : (shopSalesList || []);
    const todaySales = activeSalesData.filter(s => isMatchToday(s.saleDate || s.createdAt || s.date));
    const todaySalesRevenue = todaySales.reduce((sum, s) => sum + (Number(s.totalAmount) || 0), 0) || (dashStats.todaySales || 0);
    const todaySalesCount = todaySales.length || (dashStats.todayOrdersCount || 0);

        let todaySalesEggs = 0;
    let todaySalesProducts = 0;
    let todaySalesCash = 0;
    let todaySalesBank = 0;
    let todaySalesCredit = 0;
    let todaySalesProfit = 0;

    todaySales.forEach(s => {
      todaySalesCash += Number(s.cashPaid !== undefined ? s.cashPaid : (s.paymentMethod === 'CASH' ? s.totalAmount : 0)) || 0;
      todaySalesBank += Number(s.bankPaid !== undefined ? s.bankPaid : (s.paymentMethod === 'BANK' || s.paymentMethod === 'ONLINE' || s.paymentMethod === 'BANK_TRANSFER' ? s.totalAmount : 0)) || 0;
      todaySalesCredit += Number(s.creditDue || s.dueAmount || (s.paymentMethod === 'CREDIT' ? s.totalAmount : 0)) || 0;
      todaySalesProfit += Number(s.totalProfit !== undefined ? s.totalProfit : (Number(s.totalAmount) * 0.15)) || 0;

      let itms = Array.isArray(s.items) ? s.items : [];
      if (typeof s.items === 'string' && s.items.trim()) {
        try { itms = JSON.parse(s.items); } catch (e) { itms = []; }
      }
      if (itms && itms.length > 0) {
        itms.forEach(i => {
          todaySalesEggs += Number(i.totalEggs || i.quantity || 0);
          todaySalesProducts += Number(i.quantity || 1);
        });
      } else if (Number(s.eggsBought) > 0) {
        todaySalesEggs += Number(s.eggsBought);
        todaySalesProducts += 1;
      } else if (Number(s.petisBought) > 0) {
        todaySalesEggs += Number(s.petisBought) * 360;
        todaySalesProducts += Number(s.petisBought);
      } else {
        todaySalesProducts += 1;
      }
    });
    const todaySalesPetis = Number((todaySalesEggs / 360).toFixed(1));

    // 2. Fuel Expenses for Today
    const todayFuelList = (fuelExpensesList || []).filter(f => isMatchToday(f.expenseDate || f.createdAt || f.date));
    const todayFuelExpense = todayFuelList.reduce((sum, f) => sum + (Number(f.totalAmount) || 0), 0);
    const todayFuelCount = todayFuelList.length;
    const todayFuelLiters = todayFuelList.reduce((sum, f) => sum + (Number(f.liters) || 0), 0);

    // 3. Shop Overhead Expenses for Today
    const todayExpList = (expensesList || []).filter(e => isMatchToday(e.expenseDate || e.createdAt));
    const todayExpenses = todayExpList.reduce((sum, e) => sum + (Number(e.amount) || 0), 0);
    const todayExpensesCount = todayExpList.length;

    // 4. Damaged Stock for Today
    const todayDamagedList = (damagedProductsList || []).filter(d => isMatchToday(d.damageDate || d.createdAt));
    let todayDamagedLoss = 0;
    let todayDamagedCash = 0;
    let todayDamagedBank = 0;
    let todayDamagedCredit = 0;
    let todayDamagedEggs = 0;
    todayDamagedList.forEach(d => {
      const loss = Number(d.totalLoss) > 0
        ? Number(d.totalLoss)
        : (Number(d.lossAmount) || (Number(d.quantity || d.deductedEggs || 0) * (Number(d.unitPrice) || 0)) || 0);
      const eggs = Number(d.deductedEggs) > 0
        ? Number(d.deductedEggs)
        : (Number(d.eggQuantity || 0) + (Number(d.petiQuantity || 0) * 360) + (Number(d.trayQuantity || 0) * 30) || Number(d.quantity) || 0);
      const methodStr = String(d.paymentMethod || d.paymentSource || 'CASH').toUpperCase();
      const isBank = methodStr.includes('BANK');
      const isCredit = methodStr.includes('CREDIT') || methodStr.includes('DUE') || methodStr.includes('CLAIM') || methodStr.includes('UDHAR');

      todayDamagedLoss += loss;
      todayDamagedEggs += eggs;
      if (isCredit) todayDamagedCredit += loss;
      else if (isBank) todayDamagedBank += loss;
      else todayDamagedCash += loss;
    });
    const todayDamagedPetis = Number((todayDamagedEggs / 360).toFixed(1));

    const todayDamagedCount = todayDamagedList.length;

    // 5. Purchases & Restocks for Today
    const todayPurchasesList = (items || []).filter(p => isMatchToday(p.purchaseDate || p.createdAt || p.date));
    let todayPurchasesCost = 0;
    let todayPurchasesEggs = 0;
    let todayPurchasesCash = 0;
    let todayPurchasesBank = 0;
    let todayPurchasesDue = 0;

    todayPurchasesList.forEach(p => {
      const e = Number(p.eggQuantity || 0);
      const peti = Number(p.petiQuantity || 0);
      const tray = Number(p.trayQuantity || 0);
      const totalItemEggs = (peti * 360) + (tray * 30) + e;
      todayPurchasesEggs += totalItemEggs;

      const cost = Number(p.totalPurchaseCost || p.purchaseCost || p.totalCost) ||
        (Number(p.costPrice || 0) * (totalItemEggs / (p.unitType === 'peti' ? 360 : p.unitType === 'tray' ? 30 : 1)));
      todayPurchasesCost += Math.round(cost);

      todayPurchasesCash += Number(p.cashPaid || p.amountPaidCash || 0);
      todayPurchasesBank += Number(p.bankPaid || p.amountPaidBank || 0);
      todayPurchasesDue += Number(p.dueAmount || p.balanceDue || 0);
    });
    const todayPurchasesPetis = Number((todayPurchasesEggs / 360).toFixed(1));
    const todayPurchasesCount = todayPurchasesList.length;

    // 6. Registered Customers Activity for Today
    const todayCustomersList = (unifiedCustomersList || []).filter(c => isMatchToday(c.createdAt || c.dateAdded));
    const todayCustomersCount = todayCustomersList.length;

    // 7. Net Profit & Loss for Today
    const calcNetProfit = todaySalesProfit - todayFuelExpense - todayExpenses - todayDamagedLoss;
    const todayNetProfit = calcNetProfit > 0 ? Math.round(calcNetProfit) : (todaySalesRevenue > 0 ? Math.round(todaySalesRevenue * 0.15) : 0);
    const todayTotalLoss = calcNetProfit < 0 ? Math.round(Math.abs(calcNetProfit)) : todayDamagedLoss;

    return {
      todaySalesRevenue,
      todaySalesCount,
      todaySalesProducts: todaySalesProducts || todaySalesCount,
      todaySalesEggs,
      todaySalesPetis,
      todaySalesCash,
      todaySalesBank,
      todaySalesCredit,
      todaySalesProfit,
      todayFuelExpense,
      todayFuelCount,
      todayFuelLiters,
      todayExpenses,
      todayExpensesCount,
      todayDamagedLoss,
      todayDamagedCash,
      todayDamagedBank,
      todayDamagedCredit,
      todayDamagedEggs,
      todayDamagedPetis,
      todayDamagedCount,
      todayPurchasesCost,
      todayPurchasesEggs,
      todayPurchasesPetis,
      todayPurchasesCash,
      todayPurchasesBank,
      todayPurchasesDue,
      todayPurchasesCount,
      todayCustomersCount,
      todayNetProfit,
      todayTotalLoss
    };
  }, [unifiedSalesList, shopSalesList, items, fuelExpensesList, expensesList, damagedProductsList, unifiedCustomersList, dashStats]);

  // ─── TODAY SALE HISTORY MEMOIZED DATA & EXPORTS ───
  const isDateTodayHelper = (raw) => {
    if (!raw) return false;
    const d = new Date(raw);
    if (isNaN(d.getTime())) return false;
    const now = new Date();
    if (d.toDateString() === now.toDateString()) return true;
    const todayStr = now.toISOString().split('T')[0];
    const localToday = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
    const dLocal = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    return dLocal === localToday || d.toISOString().split('T')[0] === todayStr;
  };

  const todayAllSalesList = useMemo(() => {
    const list = (unifiedSalesList && unifiedSalesList.length > 0) ? unifiedSalesList : (shopSalesList || []);
    return list.filter(s => isDateTodayHelper(s.saleDate || s.createdAt || s.date));
  }, [unifiedSalesList, shopSalesList]);

  const todayAllExpensesList = useMemo(() => {
    return (expensesList || []).filter(e => isDateTodayHelper(e.expenseDate || e.createdAt));
  }, [expensesList]);

  const todayAllDamagedList = useMemo(() => {
    return (damagedProductsList || []).filter(d => isDateTodayHelper(d.damageDate || d.createdAt));
  }, [damagedProductsList]);

  const todayAllPurchasesList = useMemo(() => {
    return (items || []).filter(p => isDateTodayHelper(p.purchaseDate || p.createdAt || p.date));
  }, [items]);

  const todayExpensesCashAmount = useMemo(() => {
    return todayAllExpensesList.filter(e => {
      const m = String(e.paymentMethod || 'CASH').toUpperCase();
      return !m.includes('BANK') && !m.includes('ONLINE');
    }).reduce((sum, e) => sum + (Number(e.amount) || 0), 0);
  }, [todayAllExpensesList]);

  const todayExpensesBankAmount = useMemo(() => {
    return todayAllExpensesList.filter(e => {
      const m = String(e.paymentMethod || '').toUpperCase();
      return m.includes('BANK') || m.includes('ONLINE');
    }).reduce((sum, e) => sum + (Number(e.amount) || 0), 0);
  }, [todayAllExpensesList]);

  const todayNetCashInDrawer = useMemo(() => {
    return (todayMasterMetrics.todaySalesCash || 0) - todayExpensesCashAmount - (todayMasterMetrics.todayPurchasesCash || 0);
  }, [todayMasterMetrics, todayExpensesCashAmount]);

  const filteredTodayBills = useMemo(() => {
    return todayAllSalesList.filter(sale => {
      const matchSearch = !todayHistorySearch.trim() || (() => {
        const q = todayHistorySearch.toLowerCase().trim();
        const inv = String(sale.invoiceNumber || sale.serialNumber || '').toLowerCase();
        const cust = String(sale.customerName || '').toLowerCase();
        const phone = String(sale.customerPhone || sale.phone || '').toLowerCase();
        let itmsStr = '';
        if (Array.isArray(sale.items)) {
          itmsStr = sale.items.map(i => i.name || '').join(' ').toLowerCase();
        }
        return inv.includes(q) || cust.includes(q) || phone.includes(q) || itmsStr.includes(q);
      })();

      const matchPay = todayHistoryPaymentFilter === 'ALL' || (() => {
        const method = String(sale.paymentMethod || 'CASH').toUpperCase();
        if (todayHistoryPaymentFilter === 'CASH') return method === 'CASH' || (Number(sale.cashPaid) > 0);
        if (todayHistoryPaymentFilter === 'BANK') return method.includes('BANK') || method.includes('ONLINE') || (Number(sale.bankPaid) > 0);
        if (todayHistoryPaymentFilter === 'CREDIT') return method === 'CREDIT' || (Number(sale.dueAmount) > 0) || sale.isCredit;
        return true;
      })();

      return matchSearch && matchPay;
    });
  }, [todayAllSalesList, todayHistorySearch, todayHistoryPaymentFilter]);

  const todayExpensesCreditAmount = useMemo(() => {
    return todayAllExpensesList.filter(e => {
      const m = String(e.paymentMethod || '').toUpperCase();
      return m.includes('CREDIT') || m.includes('DUE') || m.includes('UDHAR') || m.includes('PAYABLE');
    }).reduce((sum, e) => sum + (Number(e.amount) || 0), 0);
  }, [todayAllExpensesList]);

  const todayPurchasesCreditDue = useMemo(() => {
    return todayAllPurchasesList.reduce((sum, p) => {
      const cost = Number(p.totalPurchaseCost || p.purchaseCost || p.totalCost) || 0;
      const paid = Number(p.cashPaid || p.amountPaidCash || 0) + Number(p.bankPaid || p.amountPaidBank || 0);
      const due = (p.dueAmount !== undefined && Number(p.dueAmount) > 0) ? Number(p.dueAmount) : Math.max(0, cost - paid);
      return sum + due;
    }, 0);
  }, [todayAllPurchasesList]);

  const filteredTodayExpenses = useMemo(() => {
    return todayAllExpensesList.filter(exp => {
      const matchSearch = !todayHistorySearch.trim() || (() => {
        const q = todayHistorySearch.toLowerCase().trim();
        const t = String(exp.title || '').toLowerCase();
        const c = String(exp.category || '').toLowerCase();
        const n = String(exp.notes || exp.createdBy || '').toLowerCase();
        return t.includes(q) || c.includes(q) || n.includes(q);
      })();

      const matchPay = todayExpensesPaymentFilter === 'ALL' || (() => {
        const m = String(exp.paymentMethod || 'CASH').toUpperCase();
        if (todayExpensesPaymentFilter === 'CASH') return !m.includes('BANK') && !m.includes('ONLINE') && !m.includes('CREDIT');
        if (todayExpensesPaymentFilter === 'BANK') return m.includes('BANK') || m.includes('ONLINE');
        if (todayExpensesPaymentFilter === 'CREDIT') return m.includes('CREDIT') || m.includes('DUE') || m.includes('UDHAR') || m.includes('PAYABLE');
        return true;
      })();

      return matchSearch && matchPay;
    });
  }, [todayAllExpensesList, todayHistorySearch, todayExpensesPaymentFilter]);

  const filteredTodayDamaged = useMemo(() => {
    return todayAllDamagedList.filter(dmg => {
      const matchSearch = !todayHistorySearch.trim() || (() => {
        const q = todayHistorySearch.toLowerCase().trim();
        const p = String(dmg.productName || '').toLowerCase();
        const r = String(dmg.reason || '').toLowerCase();
        return p.includes(q) || r.includes(q);
      })();

      const matchPay = todayDamagedPaymentFilter === 'ALL' || (() => {
        const m = String(dmg.paymentMethod || dmg.paymentSource || 'CASH').toUpperCase();
        if (todayDamagedPaymentFilter === 'CASH') return m.includes('CASH') || (!m.includes('BANK') && !m.includes('CREDIT') && !m.includes('CLAIM'));
        if (todayDamagedPaymentFilter === 'BANK') return m.includes('BANK') || m.includes('ONLINE');
        if (todayDamagedPaymentFilter === 'CREDIT') return m.includes('CREDIT') || m.includes('CLAIM') || m.includes('DUE');
        return true;
      })();

      return matchSearch && matchPay;
    });
  }, [todayAllDamagedList, todayHistorySearch, todayDamagedPaymentFilter]);

  const filteredTodayPurchases = useMemo(() => {
    return todayAllPurchasesList.filter(purch => {
      const matchSearch = !todayHistorySearch.trim() || (() => {
        const q = todayHistorySearch.toLowerCase().trim();
        const p = String(purch.name || purch.productName || '').toLowerCase();
        const s = String(purch.supplier || purch.vendorName || '').toLowerCase();
        return p.includes(q) || s.includes(q);
      })();

      const matchPay = todayPurchasesPaymentFilter === 'ALL' || (() => {
        const m = String(purch.paymentMethod || 'CASH').toUpperCase();
        const cashPaid = Number(purch.cashPaid || 0);
        const bankPaid = Number(purch.bankPaid || 0);
        const due = (purch.dueAmount !== undefined && Number(purch.dueAmount) > 0) ? Number(purch.dueAmount) : Math.max(0, (Number(purch.totalPurchaseCost || purch.purchaseCost || purch.totalCost) || 0) - (cashPaid + bankPaid));
        if (todayPurchasesPaymentFilter === 'CASH') return cashPaid > 0 || (m === 'CASH' && due <= 0);
        if (todayPurchasesPaymentFilter === 'BANK') return bankPaid > 0 || m.includes('BANK') || m.includes('ONLINE');
        if (todayPurchasesPaymentFilter === 'CREDIT') return due > 0 || m === 'CREDIT' || m.includes('DUE');
        return true;
      })();

      return matchSearch && matchPay;
    });
  }, [todayAllPurchasesList, todayHistorySearch, todayPurchasesPaymentFilter]);

