  const handleWhatsAppTodayFullReport = () => {
    const shopName = shop?.name || 'POS System';
    const dateFormatted = new Date().toLocaleDateString('en-PK', { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' });
    const timeFormatted = new Date().toLocaleTimeString('en-PK', { hour: '2-digit', minute: '2-digit' });

    let message = `📊 *${shopName.toUpperCase()} - TODAY DAILY SALES & FINANCIAL STATEMENT*\n`;
    message += `━━━━━━━━━━━━━━━━━━━━\n`;
    message += `📅 *Date:* ${dateFormatted} (${timeFormatted})\n`;
    message += `🏢 *Store / Branch:* ${shopName}\n`;
    message += `━━━━━━━━━━━━━━━━━━━━\n`;
    message += `💵 *TODAY FINANCIAL PILLARS SUMMARY:*\n`;
    message += `• *Gross Sales Revenue:* Rs. ${(todayMasterMetrics.todaySalesRevenue || 0).toLocaleString('en-PK')} (${todayAllSalesList.length} Bills)\n`;
    message += `  - Cash Inflow: Rs. ${(todayMasterMetrics.todaySalesCash || 0).toLocaleString('en-PK')}\n`;
    message += `  - Bank / Online: Rs. ${(todayMasterMetrics.todaySalesBank || 0).toLocaleString('en-PK')}\n`;
    message += `  - Credit Due: Rs. ${(todayMasterMetrics.todaySalesCredit || 0).toLocaleString('en-PK')}\n`;
    message += `• *Shop Operating Expenses:* Rs. ${(todayMasterMetrics.todayExpenses || 0).toLocaleString('en-PK')} (${todayAllExpensesList.length} Logs)\n`;
    message += `  - Cash Paid: Rs. ${todayExpensesCashAmount.toLocaleString('en-PK')} | Bank: Rs. ${todayExpensesBankAmount.toLocaleString('en-PK')}\n`;
    message += `• *Damaged Product Loss:* Rs. ${(todayMasterMetrics.todayDamagedLoss || 0).toLocaleString('en-PK')} (${todayMasterMetrics.todayDamagedEggs || 0} Units)\n`;
    message += `• *Purchases & Restocks:* Rs. ${(todayMasterMetrics.todayPurchasesCost || 0).toLocaleString('en-PK')} (${todayAllPurchasesList.length} Restocks)\n`;
    message += `  - Paid Cash: Rs. ${(todayMasterMetrics.todayPurchasesCash || 0).toLocaleString('en-PK')} | Due: Rs. ${(todayMasterMetrics.todayPurchasesDue || 0).toLocaleString('en-PK')}\n`;
    message += `━━━━━━━━━━━━━━━━━━━━\n`;
    message += `💰 *NET CASH IN DRAWER:* *Rs. ${todayNetCashInDrawer.toLocaleString('en-PK')}*\n`;
    message += `📈 *ESTIMATED NET PROFIT:* *Rs. ${(todayMasterMetrics.todayNetProfit || 0).toLocaleString('en-PK')}*\n`;
    message += `━━━━━━━━━━━━━━━━━━━━\n`;

    if (todayAllSalesList.length > 0) {
      message += `🧾 *TODAY'S CUSTOMER BILLS:*\n`;
      todayAllSalesList.slice(0, 10).forEach((s, idx) => {
        const inv = s.invoiceNumber || `#${s.serialNumber || idx + 1}`;
        const cust = s.customerName || 'Walk-in';
        const total = Number(s.totalAmount) || 0;
        const method = s.paymentMethod || 'CASH';
        message += `${idx + 1}. *${inv}* - ${cust} | Rs. ${total.toLocaleString('en-PK')} (${method})\n`;
      });
      if (todayAllSalesList.length > 10) {
        message += `_...and ${todayAllSalesList.length - 10} more customer bills._\n`;
      }
    } else {
      message += `_No customer bills recorded today yet._\n`;
    }

    message += `━━━━━━━━━━━━━━━━━━━━\n`;
    message += `_Generated via ${shopName} POS Software_`;

    const encodedText = encodeURIComponent(message);
    window.open(`https://api.whatsapp.com/send?text=${encodedText}`, '_blank');
  };

